/**
 * Constantes de negócio centralizadas — single source of truth.
 * Nenhuma regra de negócio deve ser hardcoded nos componentes.
 */

// ─── Financeiro ───────────────────────────────────────────────────────────────

/** Percentual cobrado como sinal no momento da reserva (40%) */
export const PERCENTUAL_SINAL = 0.4;

/** Horas mínimas de antecedência para cancelamento sem cobrança */
export const TOLERANCIA_CANCELAMENTO_HORAS = 24;

/** Tabela de preços por faixa de horário (R$/hora) */
export const PRECOS = {
  MANHA: 70, // 08:00 – 11:59
  TARDE: 90, // 12:00 – 16:59
  NOITE: 110, // 17:00 – 21:59
} as const;

// ─── Agendamento ──────────────────────────────────────────────────────────────

/** Quantidade de dias no futuro disponíveis para agendamento (hoje + 7) */
export const DIAS_AGENDAMENTO_FUTURO = 7;

// ─── Complexo ─────────────────────────────────────────────────────────────────

export const NOME_COMPLEXO = "Complexo Esportivo Reservei";
export const ENDERECO_COMPLEXO = "Rua das Quadras, 100 – Centro";
export const TELEFONE_COMPLEXO = "(11) 99999-0000";

// ─── Funções Utilitárias ──────────────────────────────────────────────────────

/**
 * Retorna o valor (R$) cobrado por hora de acordo com o horário de início.
 * Regra: manhã (08-11h) R$70 | tarde (12-16h) R$90 | noite (17-22h) R$110
 */
export function calcularValorHora(horaInicio: string): number {
  const hora = parseInt(horaInicio.split(":")[0], 10);
  if (hora >= 8 && hora < 12) return PRECOS.MANHA;
  if (hora >= 12 && hora < 17) return PRECOS.TARDE;
  return PRECOS.NOITE;
}

/** Soma os valores de cada slot horário selecionado */
export function calcularValorTotal(horarios: string[]): number {
  return horarios.reduce((total, h) => total + calcularValorHora(h), 0);
}

/** Valor do sinal (40% do total, arredondado para centavos) */
export function calcularValorSinal(valorTotal: number): number {
  return Math.round(valorTotal * PERCENTUAL_SINAL * 100) / 100;
}

/** Valor pendente após pagamento do sinal */
export function calcularValorPendente(valorTotal: number): number {
  return Math.round(valorTotal * (1 - PERCENTUAL_SINAL) * 100) / 100;
}

/** Formata valor monetário em Real brasileiro */
export function formatarMoeda(valor: number): string {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

/** Formata data ISO "YYYY-MM-DD" para exibição amigável */
export function formatarDataExibicao(
  dataISO: string,
  opts: Intl.DateTimeFormatOptions = {
    weekday: "short",
    day: "numeric",
    month: "short",
  }
): string {
  const [year, month, day] = dataISO.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString("pt-BR", opts);
}

/** Verifica se os horários selecionados são estritamente consecutivos */
export function saoConsecutivos(horarios: string[]): boolean {
  if (horarios.length <= 1) return true;
  const sorted = [...horarios].sort();
  for (let i = 1; i < sorted.length; i++) {
    const prev = parseInt(sorted[i - 1].split(":")[0], 10);
    const curr = parseInt(sorted[i].split(":")[0], 10);
    if (curr - prev !== 1) return false;
  }
  return true;
}

/** Gera os próximos N dias (hoje inclusive) no formato "YYYY-MM-DD" */
export function gerarDiasDisponiveis(
  total: number = DIAS_AGENDAMENTO_FUTURO + 1
): string[] {
  const result: string[] = [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let i = 0; i < total; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    result.push(d.toISOString().split("T")[0]);
  }
  return result;
}

/** Retorna a data de hoje no formato "YYYY-MM-DD" */
export function getHoje(): string {
  return new Date().toISOString().split("T")[0];
}

/** Mascara WhatsApp: (00) 00000-0000 */
export function mascaraWhatsApp(valor: string): string {
  const nums = valor.replace(/\D/g, "").slice(0, 11);
  if (nums.length <= 2) return `(${nums}`;
  if (nums.length <= 7) return `(${nums.slice(0, 2)}) ${nums.slice(2)}`;
  return `(${nums.slice(0, 2)}) ${nums.slice(2, 7)}-${nums.slice(7)}`;
}

/** Mascara CPF: 000.000.000-00 */
export function mascaraCPF(valor: string): string {
  const nums = valor.replace(/\D/g, "").slice(0, 11);
  if (nums.length <= 3) return nums;
  if (nums.length <= 6) return `${nums.slice(0, 3)}.${nums.slice(3)}`;
  if (nums.length <= 9)
    return `${nums.slice(0, 3)}.${nums.slice(3, 6)}.${nums.slice(6)}`;
  return `${nums.slice(0, 3)}.${nums.slice(3, 6)}.${nums.slice(6, 9)}-${nums.slice(9)}`;
}

/**
 * Store global — Zustand com persistência em LocalStorage.
 * ATENÇÃO: Componentes de UI não devem importar este arquivo diretamente.
 * Use o hook de abstração: @/hooks/useReservasService
 */

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Esporte } from "@/lib/quadras";

// ─── Tipos ────────────────────────────────────────────────────────────────────

export type StatusReserva =
  | "em_processamento" // lock temporário durante o checkout
  | "pendente"         // sinal pago, restante a pagar no dia
  | "confirmada"       // pagamento do sinal confirmado
  | "cancelada";       // reserva cancelada

export type StatusWhatsApp = "nao_enviado" | "enviado" | "falhou";

export interface Reserva {
  id: string;
  quadraId: string;

  // Identificação do cliente
  nomeCliente: string;
  whatsappCliente: string;
  cpfCliente: string;

  // Agendamento
  data: string;        // "YYYY-MM-DD"
  horarios: string[];  // ex: ["13:00", "14:00", "15:00"]
  horaInicio: string;  // primeiro slot
  horaFim: string;     // última hora + 1h (ex: "16:00")

  // Financeiro
  valorTotal: number;
  valorSinal: number;    // 40% do total
  valorPendente: number; // 60% do total

  // Estado
  status: StatusReserva;
  statusWhatsApp: StatusWhatsApp;
  criadaEm: string; // ISO datetime

  // Opcionais
  esporte?: Esporte;
  observacoes?: string;
}

// ─── State & Actions ──────────────────────────────────────────────────────────

interface ReservasState {
  reservas: Reserva[];

  // Mutations
  adicionarReserva: (reserva: Reserva) => void;
  atualizarReserva: (id: string, dados: Partial<Reserva>) => void;
  removerReserva: (id: string) => void;

  // Computed helpers (usados pelo service)
  getReservaById: (id: string) => Reserva | undefined;
  getReservasPorData: (data: string) => Reserva[];
}

// ─── Store ────────────────────────────────────────────────────────────────────

export const useReservasStore = create<ReservasState>()(
  persist(
    (set, get) => ({
      reservas: [],

      adicionarReserva: (reserva) =>
        set((state) => ({ reservas: [...state.reservas, reserva] })),

      atualizarReserva: (id, dados) =>
        set((state) => ({
          reservas: state.reservas.map((r) =>
            r.id === id ? { ...r, ...dados } : r
          ),
        })),

      removerReserva: (id) =>
        set((state) => ({
          reservas: state.reservas.filter((r) => r.id !== id),
        })),

      getReservaById: (id) => get().reservas.find((r) => r.id === id),

      getReservasPorData: (data) =>
        get().reservas.filter((r) => r.data === data),
    }),
    {
      name: "reservei-v2", // versão da chave no LocalStorage
    }
  )
);

/**
 * Camada de abstração entre a UI e o estado global (Zustand).
 * Nenhum componente de UI deve importar o Zustand diretamente.
 * Este hook é o único ponto de acesso ao estado de reservas.
 */

"use client";

import { useCallback, useMemo } from "react";
import { useReservasStore, type Reserva, type StatusReserva } from "@/store/useReservasStore";
import {
  calcularValorSinal,
  calcularValorPendente,
  calcularValorTotal,
} from "@/lib/constants";
import type { Esporte } from "@/lib/quadras";

// ─── Tipos de entrada para criação ───────────────────────────────────────────

export interface DadosCriacaoReserva {
  quadraId: string;
  data: string;
  horarios: string[];
  nomeCliente?: string;
  whatsappCliente?: string;
  cpfCliente?: string;
  esporte?: Esporte;
  observacoes?: string;
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useReservasService() {
  const { reservas, adicionarReserva, atualizarReserva, removerReserva } =
    useReservasStore();

  // ── Queries ────────────────────────────────────────────────────────────────

  /** Reservas ativas para uma data e quadra específicas (exclui canceladas) */
  const getHorariosOcupados = useCallback(
    (data: string, quadraId: string): string[] => {
      return reservas
        .filter(
          (r) =>
            r.data === data &&
            r.quadraId === quadraId &&
            r.status !== "cancelada"
        )
        .flatMap((r) => r.horarios);
    },
    [reservas]
  );

  /** Verifica se um horário específico está ocupado numa quadra/data */
  const isHorarioOcupado = useCallback(
    (data: string, quadraId: string, horario: string): boolean => {
      return getHorariosOcupados(data, quadraId).includes(horario);
    },
    [getHorariosOcupados]
  );

  /** Retorna todos os horários ocupados em qualquer quadra para um dia */
  const getHorariosOcupadosDia = useCallback(
    (data: string): { quadraId: string; horario: string }[] => {
      return reservas
        .filter((r) => r.data === data && r.status !== "cancelada")
        .flatMap((r) => r.horarios.map((h) => ({ quadraId: r.quadraId, horario: h })));
    },
    [reservas]
  );

  /** Reservas para o Dashboard Admin */
  const getTodasReservas = useCallback((): Reserva[] => reservas, [reservas]);

  /** Totais financeiros */
  const financeiro = useMemo(() => {
    const confirmadas = reservas.filter((r) => r.status === "confirmada");
    const naoCaneladas = reservas.filter((r) => r.status !== "cancelada");
    return {
      totalConfirmado: confirmadas.reduce((acc, r) => acc + r.valorSinal, 0),
      totalPrevisto: naoCaneladas.reduce((acc, r) => acc + r.valorTotal, 0),
      pendenteSinalConfirmado: confirmadas.reduce(
        (acc, r) => acc + r.valorPendente,
        0
      ),
    };
  }, [reservas]);

  // ── Mutations ──────────────────────────────────────────────────────────────

  /**
   * Cria uma reserva com status "em_processamento" (lock temporário).
   * Retorna o ID gerado para controle do fluxo de checkout.
   */
  const criarReservaEmProcessamento = useCallback(
    (dados: DadosCriacaoReserva): string => {
      const horarios = [...dados.horarios].sort();
      const valorTotal = calcularValorTotal(horarios);
      const id = `rsv_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

      const reserva: Reserva = {
        id,
        quadraId: dados.quadraId,
        data: dados.data,
        horarios,
        horaInicio: horarios[0],
        horaFim: `${String(parseInt(horarios[horarios.length - 1]) + 1).padStart(2, "0")}:00`,
        nomeCliente: dados.nomeCliente ?? "",
        whatsappCliente: dados.whatsappCliente ?? "",
        cpfCliente: dados.cpfCliente ?? "",
        valorTotal,
        valorSinal: calcularValorSinal(valorTotal),
        valorPendente: calcularValorPendente(valorTotal),
        status: "em_processamento",
        statusWhatsApp: "nao_enviado",
        criadaEm: new Date().toISOString(),
        esporte: dados.esporte,
        observacoes: dados.observacoes,
      };

      adicionarReserva(reserva);
      return id;
    },
    [adicionarReserva]
  );

  /**
   * Atualiza os dados de identificação de uma reserva em processamento
   * e mantém o status "em_processamento".
   */
  const atualizarIdentificacao = useCallback(
    (
      id: string,
      dados: Pick<Reserva, "nomeCliente" | "whatsappCliente" | "cpfCliente"> & {
        esporte?: Esporte;
        observacoes?: string;
      }
    ) => {
      atualizarReserva(id, dados);
    },
    [atualizarReserva]
  );

  /**
   * Confirma o pagamento do sinal — reserva fica como "pendente"
   * (sinal pago, restante a pagar no dia).
   * Também simula o envio do WhatsApp.
   */
  const confirmarPagamentoSinal = useCallback(
    (id: string) => {
      atualizarReserva(id, {
        status: "pendente",
        statusWhatsApp: "enviado",
      });
    },
    [atualizarReserva]
  );

  /** Cancela e libera o lock de uma reserva em processamento */
  const liberarLock = useCallback(
    (id: string) => {
      removerReserva(id);
    },
    [removerReserva]
  );

  /** Admin: cancela uma reserva confirmada */
  const cancelarReserva = useCallback(
    (id: string) => {
      atualizarReserva(id, { status: "cancelada" });
    },
    [atualizarReserva]
  );

  /** Admin: atualiza qualquer campo de uma reserva */
  const atualizarStatus = useCallback(
    (id: string, status: StatusReserva) => {
      atualizarReserva(id, { status });
    },
    [atualizarReserva]
  );

  return {
    // Queries
    reservas,
    getHorariosOcupados,
    isHorarioOcupado,
    getHorariosOcupadosDia,
    getTodasReservas,
    financeiro,

    // Mutations
    criarReservaEmProcessamento,
    atualizarIdentificacao,
    confirmarPagamentoSinal,
    liberarLock,
    cancelarReserva,
    atualizarStatus,
  };
}

