"use client";

import { cn } from "@/lib/utils";
import { HORARIOS_DISPONIVEIS } from "@/lib/quadras";
import {
  calcularValorHora,
  formatarMoeda,
  saoConsecutivos,
} from "@/lib/constants";
import { toast } from "sonner";

interface Props {
  quadraId: string | null;
  horariosSelecionados: string[];      // slots no carrinho do usuário atual
  horariosOcupados: string[];          // slots de outras reservas (persistidas)
  onToggleHorario: (horario: string) => void;
}

const FAIXA_LABEL: Record<string, string> = {
  MANHA: "Manhã · R$ 70/h",
  TARDE: "Tarde · R$ 90/h",
  NOITE: "Noite · R$ 110/h",
};

function getFaixa(hora: number): "MANHA" | "TARDE" | "NOITE" {
  if (hora >= 8 && hora < 12) return "MANHA";
  if (hora >= 12 && hora < 17) return "TARDE";
  return "NOITE";
}

export function HorarioGrid({
  quadraId,
  horariosSelecionados,
  horariosOcupados,
  onToggleHorario,
}: Props) {
  if (!quadraId) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center">
        <div className="w-14 h-14 rounded-full bg-slate-800 flex items-center justify-center mb-4">
          <span className="text-2xl">🏟️</span>
        </div>
        <p className="text-slate-500 text-sm">
          Selecione uma quadra acima para ver os horários disponíveis.
        </p>
      </div>
    );
  }

  // Agrupa por faixa para exibir labels de seção
  let ultimaFaixa = "";

  const handleClick = (horario: string) => {
    const isOcupado = horariosOcupados.includes(horario);
    if (isOcupado) return;

    const isSelecionado = horariosSelecionados.includes(horario);

    if (!isSelecionado) {
      // Verifica se adicionando este slot a seleção ainda seria consecutiva
      const proximo = [...horariosSelecionados, horario];
      if (!saoConsecutivos(proximo)) {
        toast.error("Selecione horários consecutivos", {
          description: "Ex: 13h → 14h → 15h. Não é possível pular horários.",
        });
        return;
      }
    }

    onToggleHorario(horario);
  };

  return (
    <div className="w-full">
      <p className="text-xs font-semibold uppercase tracking-widest text-slate-500 mb-4">
        Horários disponíveis
      </p>
      <div className="space-y-1">
        {HORARIOS_DISPONIVEIS.map((horario) => {
          const hora = parseInt(horario.split(":")[0], 10);
          const faixa = getFaixa(hora);
          const showLabel = faixa !== ultimaFaixa;
          if (showLabel) ultimaFaixa = faixa;

          const isSelecionado = horariosSelecionados.includes(horario);
          const isOcupado = horariosOcupados.includes(horario);
          const valorHora = calcularValorHora(horario);

          return (
            <div key={horario}>
              {showLabel && (
                <p className="text-[10px] font-semibold uppercase tracking-widest text-slate-600 mt-4 mb-2 pl-1">
                  {FAIXA_LABEL[faixa]}
                </p>
              )}
              <button
                onClick={() => handleClick(horario)}
                disabled={isOcupado}
                className={cn(
                  "w-full flex items-center justify-between px-4 py-3 rounded-xl border text-sm font-medium transition-all duration-150",
                  isSelecionado
                    ? "bg-emerald-500/20 border-emerald-500 text-emerald-300 shadow-sm shadow-emerald-500/20"
                    : isOcupado
                    ? "bg-slate-900/50 border-slate-800 text-slate-600 cursor-not-allowed"
                    : "bg-slate-800/40 border-slate-700/60 text-slate-300 hover:bg-slate-700 hover:border-slate-600 active:scale-[0.99]"
                )}
              >
                <div className="flex items-center gap-3">
                  <span
                    className={cn(
                      "w-2 h-2 rounded-full flex-shrink-0",
                      isSelecionado
                        ? "bg-emerald-400"
                        : isOcupado
                        ? "bg-red-700"
                        : "bg-slate-600"
                    )}
                  />
                  <span>
                    {horario} – {String(hora + 1).padStart(2, "0")}:00
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  {isOcupado ? (
                    <span className="text-xs text-red-700 font-semibold">
                      Ocupado
                    </span>
                  ) : (
                    <>
                      <span className="text-xs text-slate-500">
                        {formatarMoeda(valorHora)}
                      </span>
                      {isSelecionado && (
                        <span className="text-xs bg-emerald-500/30 text-emerald-300 px-2 py-0.5 rounded-full">
                          ✓
                        </span>
                      )}
                    </>
                  )}
                </div>
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

