"use client";

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { mascaraWhatsApp, mascaraCPF, TOLERANCIA_CANCELAMENTO_HORAS } from "@/lib/constants";
import { ESPORTES, type Esporte } from "@/lib/quadras";
import { User, Phone, CreditCard, ChevronRight } from "lucide-react";

interface DadosIdentificacao {
  nome: string;
  whatsapp: string;
  cpf: string;
  esporte: Esporte | "";
  observacoes: string;
}

interface Props {
  open: boolean;
  onClose: () => void;
  onConfirmar: (dados: DadosIdentificacao) => void;
}

const initialState: DadosIdentificacao = {
  nome: "",
  whatsapp: "",
  cpf: "",
  esporte: "",
  observacoes: "",
};

export function FormularioIdentificacao({ open, onClose, onConfirmar }: Props) {
  const [dados, setDados] = useState<DadosIdentificacao>(initialState);
  const [errors, setErrors] = useState<Partial<Record<keyof DadosIdentificacao, string>>>({});

  const set = (campo: keyof DadosIdentificacao, valor: string) => {
    setDados((prev) => ({ ...prev, [campo]: valor }));
    if (errors[campo]) setErrors((prev) => ({ ...prev, [campo]: undefined }));
  };

  const validar = (): boolean => {
    const novosErrors: typeof errors = {};
    if (!dados.nome.trim() || dados.nome.trim().length < 3)
      novosErrors.nome = "Informe seu nome completo.";
    if (dados.whatsapp.replace(/\D/g, "").length < 11)
      novosErrors.whatsapp = "WhatsApp inválido. Use DDD + número.";
    if (dados.cpf.replace(/\D/g, "").length !== 11)
      novosErrors.cpf = "CPF inválido.";
    setErrors(novosErrors);
    return Object.keys(novosErrors).length === 0;
  };

  const handleSubmit = () => {
    if (!validar()) return;
    onConfirmar(dados);
  };

  const handleClose = () => {
    setDados(initialState);
    setErrors({});
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && handleClose()}>
      <DialogContent className="bg-slate-900 border-slate-700 text-white max-w-md mx-auto">
        <DialogHeader>
          <DialogTitle className="text-xl font-bold">Seus dados</DialogTitle>
          <DialogDescription className="text-slate-400">
            Informe seus dados para finalizar a reserva. Não é necessário criar
            conta.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 pt-2">
          {/* Nome */}
          <div className="space-y-1.5">
            <Label className="text-slate-300 text-sm font-medium flex items-center gap-1.5">
