          {/* Observações */}
          <div className="space-y-1.5">
            <Label className="text-slate-300 text-sm font-medium">
              Observações <span className="text-slate-500 font-normal">(opcional)</span>
            </Label>
            <Input
              value={dados.observacoes}
              onChange={(e) => set("observacoes", e.target.value)}
              placeholder="Ex.: trazer colete, preferência de lado..."
              className="bg-slate-800 border-slate-700 text-white placeholder:text-slate-500 focus:border-emerald-500"
            />
          </div>

          <Separator className="bg-slate-700/50" />

          {/* Termos */}
          <div className="bg-slate-800/50 rounded-xl p-3 border border-slate-700/50">
            <p className="text-[11px] text-slate-400 leading-relaxed">
              <strong className="text-slate-300">Política de cancelamento:</strong>{" "}
              Cancelamentos realizados com mais de{" "}
              <strong className="text-white">
                {TOLERANCIA_CANCELAMENTO_HORAS}h de antecedência
              </strong>{" "}
              são reembolsados integralmente. Abaixo desse prazo, o sinal não
              será devolvido. Ao prosseguir, você concorda com os termos.
