// ── Fake QR Code SVG ──────────────────────────────────────────────────────────

const QR_ROWS = [
  "1111111011101111111",
  "1000001001001000001",
  "1011101010101011101",
  "1011101001011011101",
  "1011101010101011101",
  "1000001001001000001",
  "1111111010101111111",
  "0000000001100000000",
  "1101011111001011011",
  "0010100101010100100",
  "1001011010101011001",
  "0100000001010010010",
  "1101011011011011011",
  "0000000001110001001",
  "1111111010101110111",
  "1000001001011001001",
  "1011101011001010111",
  "1000001001010100001",
  "1111111010101111111",
];

function FakeQrCode() {
  const size = 19;
  const cellSize = 10;
  const total = size * cellSize;

  return (
    <svg
      width={total}
      height={total}
      viewBox={`0 0 ${total} ${total}`}
      className="rounded-lg"
      style={{ imageRendering: "pixelated" }}
    >
      <rect width={total} height={total} fill="white" />
      {QR_ROWS.map((row, y) =>
        row.split("").map((cell, x) =>
          cell === "1" ? (
            <rect
              key={`${x}-${y}`}
              x={x * cellSize}
              y={y * cellSize}
              width={cellSize}
              height={cellSize}
              fill="#0f172a"
            />
          ) : null
        )
      )}
    </svg>
  );
}

