  (id: string, tipoPagamento: "sinal" | "integral") => {
    const reserva = getReservaById(id);
    if (!reserva) return;

    const atualizacao: Partial<Reserva> = {
      status: "pendente", // Ainda precisa comparecer
      statusWhatsApp: "enviado",
