"use client";

import { cn } from "@/lib/utils";
import { HORARIOS_DISPONIVEIS } from "@/lib/quadras";
import { calcularValorHora, saoConsecutivos } from "@/lib/constants";
import { toast } from "sonner";

interface Props {
  horariosSelecionados: string[];   // slots selecionados NESTA quadra
  horariosOcupados: string[];       // slots já reservados (persistidos)
  horariosDesabilitados?: string[]; // slots bloqueados por seleção em outra quadra
  onToggleHorario: (horario: string) => void;
}

const FAIXA: Record<string, { label: string; cor: string }> = {
  MANHA: { label: "Manhã", cor: "text-amber-400" },
  TARDE: { label: "Tarde", cor: "text-sky-400" },
  NOITE: { label: "Noite", cor: "text-violet-400" },
};

function getFaixa(hora: number): "MANHA" | "TARDE" | "NOITE" {
  if (hora >= 8 && hora < 12) return "MANHA";
  if (hora >= 12 && hora < 17) return "TARDE";
  return "NOITE";
}

const PRECO_POR_FAIXA: Record<string, string> = {
  MANHA: "R$70/h",
  TARDE: "R$90/h",
  NOITE: "R$110/h",
};

export function HorarioGrid({
  horariosSelecionados,
  horariosOcupados,
  horariosDesabilitados = [],
  onToggleHorario,
}: Props) {
  const handleClick = (horario: string) => {
    if (horariosOcupados.includes(horario)) return;
    if (horariosDesabilitados.includes(horario)) {
      toast.warning("Horário em uso", {
        description: "Você já selecionou este horário em outra quadra.",
      });
      return;
    }

    const isSelecionado = horariosSelecionados.includes(horario);
    if (!isSelecionado) {
      const proximo = [...horariosSelecionados, horario];
      if (!saoConsecutivos(proximo)) {
        toast.error("Selecione horários consecutivos", {
          description: "Ex: 13h → 14h → 15h. Não é possível pular horários.",
        });
        return;
      }
    }
    onToggleHorario(horario);
  };

  // Agrupar por faixa para os labels de seção
  const grupos: Array<{ faixa: string; horarios: string[] }> = [];
  let faixaAtual = "";
  for (const h of HORARIOS_DISPONIVEIS) {
    const f = getFaixa(parseInt(h.split(":")[0], 10));
    if (f !== faixaAtual) {
      faixaAtual = f;
      grupos.push({ faixa: f, horarios: [] });
    }
    grupos[grupos.length - 1].horarios.push(h);
  }

  return (
    <div className="space-y-3">
      {grupos.map(({ faixa, horarios }) => (
        <div key={faixa}>
          {/* Label da faixa */}
          <div className="flex items-center gap-2 mb-2">
            <span
              className={cn(
                "text-[10px] font-bold uppercase tracking-widest",
                FAIXA[faixa].cor
              )}
            >
              {FAIXA[faixa].label}
            </span>
            <span className="text-[10px] text-slate-600">
              · {PRECO_POR_FAIXA[faixa]}
            </span>
          </div>

          {/* Chips de horário horizontais */}
          <div className="flex flex-wrap gap-2">
            {horarios.map((horario) => {
              const hora = parseInt(horario.split(":")[0], 10);
              const isSelecionado = horariosSelecionados.includes(horario);
              const isOcupado = horariosOcupados.includes(horario);
              const isDesabilitado = horariosDesabilitados.includes(horario);
              const isInativo = isOcupado || isDesabilitado;

              return (
                <button
                  key={horario}
                  onClick={() => handleClick(horario)}
                  disabled={isInativo}
                  title={
                    isOcupado
                      ? "Horário ocupado"
                      : isDesabilitado
                      ? "Selecionado em outra quadra"
                      : `${horario} – ${String(hora + 1).padStart(2, "0")}:00`
                  }
                  className={cn(
                    "px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all duration-150 select-none",
                    isSelecionado
                      ? "bg-emerald-500/25 border-emerald-500 text-emerald-300 shadow-sm"
                      : isOcupado
                      ? "bg-slate-900/40 border-slate-800 text-slate-700 cursor-not-allowed line-through"
                      : isDesabilitado
                      ? "bg-slate-900/30 border-slate-800 text-slate-700 cursor-not-allowed opacity-40"
                      : "bg-slate-800/50 border-slate-700 text-slate-300 hover:bg-slate-700 hover:border-slate-600 active:scale-95"
                  )}
                >
                  {isSelecionado ? "✓ " : ""}
                  {horario}
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { COMODIDADES_COMPLEXO, type Quadra } from "@/lib/quadras";
import { HorarioGrid } from "./HorarioGrid";

interface Props {
  quadra: Quadra;
  horariosSelecionados: string[];
  horariosOcupados: string[];
  horariosDesabilitados: string[]; // selecionados em outra quadra
  isAtiva: boolean; // esta quadra está com seleção ativa?
  onToggleHorario: (horario: string, quadraId: string) => void;
}

export function QuadraHorarioItem({
  quadra,
  horariosSelecionados,
  horariosOcupados,
  horariosDesabilitados,
  isAtiva,
  onToggleHorario,
}: Props) {
  return (
    <div
      className={cn(
        "rounded-2xl border p-5 transition-all duration-200",
        isAtiva
          ? "bg-slate-800/80 border-emerald-500/40 shadow-lg shadow-emerald-500/5"
          : "bg-slate-900/60 border-slate-800"
      )}
    >
      {/* ── Header da Quadra ─────────────────────────────────────────── */}
      <div className="flex items-start justify-between mb-4">
        <div>
          <div className="flex items-center gap-2">
            {isAtiva && (
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse flex-shrink-0" />
            )}
            <h3 className="font-bold text-white text-base">
              Quadra {quadra.numero}
            </h3>
          </div>
          <p className="text-xs text-slate-500 mt-0.5">{quadra.descricao}</p>
        </div>

        {isAtiva && horariosSelecionados.length > 0 && (
          <span className="text-[10px] bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2 py-1 rounded-full font-semibold flex-shrink-0">
            {horariosSelecionados.length}h selecionada{horariosSelecionados.length > 1 ? "s" : ""}
          </span>
        )}
      </div>

      {/* ── Comodidades (collapsed, só 3) ────────────────────────────── */}
      <div className="flex flex-wrap gap-1.5 mb-4">
        {COMODIDADES_COMPLEXO.slice(0, 3).map((c) => (
          <span
            key={c}
            className="text-[10px] text-slate-500 bg-slate-800 border border-slate-700/50 px-2 py-0.5 rounded-full"
          >
            {c}
          </span>
        ))}
      </div>

      {/* ── Grade de Horários ─────────────────────────────────────────── */}
      <HorarioGrid
        horariosSelecionados={horariosSelecionados}
        horariosOcupados={horariosOcupados}
        horariosDesabilitados={horariosDesabilitados}
        onToggleHorario={(horario) => onToggleHorario(horario, quadra.id)}
      />
    </div>
  );
}

"use client";

import { useState, useCallback, useMemo } from "react";
import { toast } from "sonner";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";

import { CalendarioSelector } from "./CalendarioSelector";
import { QuadraHorarioItem } from "./QuadraHorarioItem";
import { CarrinhoLateral, BotaoCarrinhoMobile } from "./CarrinhoLateral";
import { FormularioIdentificacao } from "./FormularioIdentificacao";
import { ModalPix } from "./ModalPix";

import { useReservasService } from "@/hooks/useReservasService";
import {
  gerarDiasDisponiveis,
  getHoje,
  calcularValorTotal,
  calcularValorSinal,
  calcularValorPendente,
  saoConsecutivos,
} from "@/lib/constants";
import { QUADRAS } from "@/lib/quadras";
import type { Esporte } from "@/lib/quadras";

type Etapa = "formulario" | "pix";

interface DadosForm {
  nome: string;
  whatsapp: string;
  cpf: string;
  esporte: Esporte | "";
  observacoes: string;
}

export function PortalCliente() {
  // ── Estado de seleção ──────────────────────────────────────────────────
  const dias = useMemo(() => gerarDiasDisponiveis(), []);
  const [dataSelecionada, setDataSelecionada] = useState<string>(getHoje());
  const [quadraSelecionada, setQuadraSelecionada] = useState<string | null>(null);
  const [horariosSelecionados, setHorariosSelecionados] = useState<string[]>([]);

  // ── Checkout ────────────────────────────────────────────────────────────
  const [etapa, setEtapa] = useState<Etapa | null>(null);
  const [reservaIdAtual, setReservaIdAtual] = useState<string | null>(null);
  const [dadosForm, setDadosForm] = useState<DadosForm | null>(null);
  const [isCarrinhoOpen, setIsCarrinhoOpen] = useState(false);

  // ── Service ─────────────────────────────────────────────────────────────
  const {
    getHorariosOcupados,
    criarReservaEmProcessamento,
    atualizarIdentificacao,
    confirmarPagamento,
    liberarLock,
  } = useReservasService();

  // ── Valores calculados ──────────────────────────────────────────────────
  const valorTotal = useMemo(
    () => calcularValorTotal(horariosSelecionados),
    [horariosSelecionados]
  );
  const valorSinal = useMemo(() => calcularValorSinal(valorTotal), [valorTotal]);
  const valorPendente = useMemo(
    () => calcularValorPendente(valorTotal),
    [valorTotal]
  );

  // ── Handlers ────────────────────────────────────────────────────────────

  const handleSelectData = useCallback((data: string) => {
    setDataSelecionada(data);
    setQuadraSelecionada(null);
    setHorariosSelecionados([]);
  }, []);

  /**
   * Chamado por QuadraHorarioItem: alterna um horário na quadra especificada.
   * Garante que só uma quadra pode ter horários selecionados por vez,
   * e que múltiplos horários sejam consecutivos.
   */
  const handleToggleHorario = useCallback(
    (horario: string, quadraId: string) => {
      // Bloqueia seleção em quadra diferente da ativa
      if (quadraSelecionada !== null && quadraSelecionada !== quadraId) {
        toast.warning("Finalize ou limpe a seleção atual antes de trocar de quadra.");
        return;
      }

      setQuadraSelecionada(quadraId);

      setHorariosSelecionados((prev) => {
        if (prev.includes(horario)) {
          const next = prev.filter((h) => h !== horario);
          if (next.length === 0) setQuadraSelecionada(null);
          return next;
        }
        const next = [...prev, horario];
        // saoConsecutivos já dispara toast via HorarioGrid, retorna prev silenciosamente
        if (!saoConsecutivos(next)) return prev;
        return next;
      });
    },
    [quadraSelecionada]
  );

  const handleLimpar = useCallback(() => {
    setHorariosSelecionados([]);
    setQuadraSelecionada(null);
  }, []);

  /** Lock temporário + abertura do formulário */
  const handleContinuar = useCallback(() => {
    if (!quadraSelecionada || horariosSelecionados.length === 0) return;
    const id = criarReservaEmProcessamento({
      quadraId: quadraSelecionada,
      data: dataSelecionada,
      horarios: horariosSelecionados,
    });
    setReservaIdAtual(id);
    setIsCarrinhoOpen(false);
    setEtapa("formulario");
  }, [
    quadraSelecionada,
    horariosSelecionados,
    dataSelecionada,
    criarReservaEmProcessamento,
  ]);

  /** Formulário confirmado → abre modal Pix */
  const handleFormConfirmar = useCallback(
    (dados: DadosForm) => {
      if (!reservaIdAtual) return;
      setDadosForm(dados);
      atualizarIdentificacao(reservaIdAtual, {
        nomeCliente: dados.nome,
        whatsappCliente: dados.whatsapp,
        cpfCliente: dados.cpf,
        esporte: dados.esporte || undefined,
        observacoes: dados.observacoes || undefined,
      });
      setEtapa("pix");
    },
    [reservaIdAtual, atualizarIdentificacao]
  );

  /**
   * Simula pagamento Pix — aceita o tipo escolhido pelo usuário (sinal | integral).
   * Atualiza a store e exibe toast com mensagem dinâmica.
   */
  const handleSimularPagamento = useCallback(
    (tipo: "sinal" | "integral") => {
      if (!reservaIdAtual) return;
      confirmarPagamento(reservaIdAtual, tipo);

      // Reseta estado local
      setEtapa(null);
      setReservaIdAtual(null);
      setDadosForm(null);
      setHorariosSelecionados([]);
      setQuadraSelecionada(null);

      const descricao =
        tipo === "integral"
          ? "Pagamento integral confirmado! ✅"
          : "Sinal confirmado. O restante será pago no local. 👍";

      toast.success("Mensagem enviada no WhatsApp 📱", {
        description: descricao,
        duration: 6000,
      });
    },
    [reservaIdAtual, confirmarPagamento]
  );

  /** Cancela checkout e libera o lock */
  const handleCancelarCheckout = useCallback(() => {
    if (reservaIdAtual) liberarLock(reservaIdAtual);
    setEtapa(null);
    setReservaIdAtual(null);
    setDadosForm(null);
  }, [reservaIdAtual, liberarLock]);

  // ── Lógica de desabilitação cruzada ────────────────────────────────────
  // Horários selecionados na quadra ativa ficam desabilitados nas demais
  const horariosDesabilitadosGlobal = horariosSelecionados;

  // ── Render ──────────────────────────────────────────────────────────────

  const carrinhoContent = (
    <CarrinhoLateral
      quadraId={quadraSelecionada}
      data={dataSelecionada}
      horariosSelecionados={horariosSelecionados}
      valorTotal={valorTotal}
      valorSinal={valorSinal}
      valorPendente={valorPendente}
      onContinuar={handleContinuar}
      onLimpar={handleLimpar}
    />
  );

  return (
    <>
      <div className="min-h-screen bg-slate-950">
        {/* ── Header ──────────────────────────────────────────────────── */}
        <header className="sticky top-0 z-30 border-b border-slate-800 bg-slate-950/80 backdrop-blur-md">
          <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-2xl">🏟️</span>
              <div>
                <span className="font-black text-white text-lg tracking-tight">
                  Reservei
                </span>
                <span className="hidden sm:inline text-slate-500 text-sm ml-2">
                  · Complexo Esportivo
                </span>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-2 text-xs text-slate-500">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              Agendamento online
            </div>
          </div>
        </header>

        {/* ── Layout Principal ─────────────────────────────────────────── */}
        <div className="max-w-7xl mx-auto px-4 py-6 lg:grid lg:grid-cols-[1fr_360px] lg:gap-8 lg:items-start">
          {/* Coluna esquerda: seleção */}
          <main className="space-y-6 pb-32 lg:pb-6">
            {/* Calendário horizontal */}
            <section>
              <CalendarioSelector
                dias={dias}
                dataSelecionada={dataSelecionada}
                onSelectData={handleSelectData}
              />
            </section>

            {/* Título da seção */}
            <div>
              <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">
                Quadras disponíveis
              </p>
              <p className="text-[11px] text-slate-600 mt-1">
                Selecione o horário desejado diretamente na quadra.
              </p>
            </div>

            {/* Quadras sempre expandidas verticalmente */}
            {QUADRAS.map((quadra) => {
              const isAtiva = quadraSelecionada === quadra.id;
              const horariosOcupados = getHorariosOcupados(
                dataSelecionada,
                quadra.id
              );
              // Quadras não-ativas recebem os horários já selecionados como desabilitados
              const horariosDesabilitados = isAtiva
                ? []
                : horariosDesabilitadosGlobal;

              return (
                <QuadraHorarioItem
                  key={quadra.id}
                  quadra={quadra}
                  horariosSelecionados={isAtiva ? horariosSelecionados : []}
                  horariosOcupados={horariosOcupados}
                  horariosDesabilitados={horariosDesabilitados}
                  isAtiva={isAtiva}
                  onToggleHorario={handleToggleHorario}
                />
              );
            })}
          </main>

          {/* Coluna direita: carrinho (desktop) */}
          <aside className="hidden lg:block sticky top-24">
            <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 min-h-[400px] flex flex-col">
              {carrinhoContent}
            </div>
          </aside>
        </div>

        {/* Botão flutuante carrinho (mobile) */}
        <BotaoCarrinhoMobile
          count={horariosSelecionados.length}
          valorSinal={valorSinal}
          onClick={() => setIsCarrinhoOpen(true)}
        />
      </div>

      {/* Sheet mobile do carrinho */}
      <Sheet open={isCarrinhoOpen} onOpenChange={setIsCarrinhoOpen}>
        <SheetContent
          side="bottom"
          className="bg-slate-900 border-t border-slate-700 text-white rounded-t-3xl h-[85dvh] flex flex-col"
        >
          <SheetHeader className="flex-shrink-0">
            <SheetTitle className="text-white text-left">
              Resumo da Reserva
            </SheetTitle>
          </SheetHeader>
          <div className="flex-1 overflow-y-auto py-4">{carrinhoContent}</div>
        </SheetContent>
      </Sheet>

      {/* Modal: Formulário de identificação */}
      <FormularioIdentificacao
        open={etapa === "formulario"}
        onClose={handleCancelarCheckout}
        onConfirmar={handleFormConfirmar}
      />

      {/* Modal: Pix */}
      <ModalPix
        open={etapa === "pix"}
        valorSinal={valorSinal}
        valorTotal={valorTotal}
        nomeCliente={dadosForm?.nome ?? ""}
        onSimularPagamento={handleSimularPagamento}
        onCancelar={handleCancelarCheckout}
      />
    </>
  );
}

