  ENDERECO_COMPLEXO,
} from "@/lib/constants";
import { ESPORTES, QUADRAS, type Esporte } from "@/lib/quadras";
import {
  User,
  Phone,
  CreditCard,
  ChevronRight,
  MapPin,
  Calendar,
  Clock,
  Check,
  ShieldCheck,
} from "lucide-react";
import { cn } from "@/lib/utils";

export interface DadosIdentificacao {
  nome: string;
  whatsapp: string;
  cpf: string;
  esporte: Esporte | "";
  observacoes: string;
}

interface Props {
  open: boolean;
  onClose: () => void;
  onConfirmar: (dados: DadosIdentificacao, tipoPagamento: "sinal" | "integral") => void;
  quadraId: string | null;
  data: string;
  horariosSelecionados: string[];
  valorTotal: number;
  valorSinal: number;
  valorPendente: number;
}

const initialState: DadosIdentificacao = {
  nome: "",
  whatsapp: "",
  cpf: "",
  esporte: "",
  observacoes: "",
};

export function FormularioIdentificacao({
  open,
  onClose,
  onConfirmar,
  quadraId,
  data,
  horariosSelecionados,
  valorTotal,
  valorSinal,
  valorPendente,
}: Props) {
  const [dados, setDados] = useState<DadosIdentificacao>(initialState);
  const [tipoPagamento, setTipoPagamento] = useState<"sinal" | "integral">("sinal");
  const [errors, setErrors] = useState<Partial<Record<keyof DadosIdentificacao, string>>>({});

  const quadra = QUADRAS.find((q) => q.id === quadraId);
  const horariosOrdenados = [...horariosSelecionados].sort();
  const primeiroHorario = horariosOrdenados[0] ?? "";
  const ultimoHorario = horariosOrdenados[horariosOrdenados.length - 1];
  const ultimaHora = ultimoHorario
    ? `${String(parseInt(ultimoHorario.split(":")[0], 10) + 1).padStart(2, "0")}:00`
    : "";

  const valorCobradoAgora = tipoPagamento === "sinal" ? valorSinal : valorTotal;

  const set = (campo: keyof DadosIdentificacao, valor: string) => {
    setDados((prev) => ({ ...prev, [campo]: valor }));
    if (errors[campo]) setErrors((prev) => ({ ...prev, [campo]: undefined }));
  };

  const validar = (): boolean => {
    const novosErrors: typeof errors = {};
    if (!dados.nome.trim() || dados.nome.trim().length < 3)
      novosErrors.nome = "Informe seu nome completo.";
    if (dados.whatsapp.replace(/\D/g, "").length < 11)
      novosErrors.whatsapp = "WhatsApp inválido. Use DDD + número.";
    if (dados.cpf.replace(/\D/g, "").length !== 11)
      novosErrors.cpf = "CPF inválido.";
    setErrors(novosErrors);
    return Object.keys(novosErrors).length === 0;
  };

  const handleSubmit = () => {
    if (!validar()) return;
    onConfirmar(dados, tipoPagamento);
  };

  const handleClose = () => {
    setDados(initialState);
    setErrors({});
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && handleClose()}>
      <DialogContent className="bg-slate-900 border-slate-700 text-white max-w-4xl max-h-[90vh] overflow-y-auto p-6 md:p-8">
        <DialogHeader className="mb-4">
          <DialogTitle className="text-xl md:text-2xl font-black">
            Confirmar Reserva
          </DialogTitle>
          <DialogDescription className="text-slate-400">
            Revise as informações da sua reserva, escolha como deseja pagar e preencha seus dados para contato.
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* ── Coluna Esquerda: Resumo do Carrinho & Escolha de Pagamento ── */}
          <div className="space-y-5 bg-slate-950/60 border border-slate-800 rounded-2xl p-5 flex flex-col justify-between">
            <div className="space-y-4">
              <div className="flex items-center justify-between pb-3 border-b border-slate-800">
                <span className="text-xs font-bold uppercase tracking-widest text-slate-400">
                  Resumo da Reserva
                </span>
                {quadra && (
                  <span className="text-xs font-bold bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2.5 py-1 rounded-full">
                    Quadra {quadra.numero}
                  </span>
                )}
              </div>

              {/* Informações detalhadas */}
              <div className="space-y-3 text-sm">
                <div className="flex items-start gap-3">
                  <MapPin className="w-4 h-4 text-emerald-400 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="text-xs text-slate-500">Local</p>
                    <p className="text-slate-200 font-medium">{ENDERECO_COMPLEXO}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <Calendar className="w-4 h-4 text-emerald-400 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="text-xs text-slate-500">Data</p>
                    <p className="text-slate-200 font-medium capitalize">
                      {data ? formatarDataExibicao(data, { weekday: "long", day: "numeric", month: "long" }) : "—"}
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <Clock className="w-4 h-4 text-emerald-400 mt-0.5 flex-shrink-0" />
                  <div className="flex-1">
                    <p className="text-xs text-slate-500">Horário</p>
                    <p className="text-slate-200 font-medium">
                      {primeiroHorario} – {ultimaHora}
                      <span className="text-slate-500 ml-1.5">
                        ({horariosSelecionados.length} hora{horariosSelecionados.length > 1 ? "s" : ""})
                      </span>
                    </p>
                    <div className="flex flex-wrap gap-1.5 mt-2">
                      {horariosOrdenados.map((h) => (
                        <span
                          key={h}
                          className="text-[11px] bg-slate-800 text-emerald-400 border border-slate-700 px-2 py-0.5 rounded-md font-medium"
                        >
                          {h}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>

              <Separator className="bg-slate-800 my-4" />

              {/* ── Opção de Pagamento Prévia ── */}
              <div>
                <p className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-2.5">
                  Como deseja pagar agora?
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  {/* Opção Sinal */}
                  <button
                    type="button"
                    onClick={() => setTipoPagamento("sinal")}
                    className={cn(
                      "p-3 rounded-xl border text-left transition-all duration-200 relative",
                      tipoPagamento === "sinal"
                        ? "bg-emerald-500/15 border-emerald-500 text-white shadow-md shadow-emerald-500/10 ring-1 ring-emerald-500/50"
                        : "bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700 hover:text-slate-300"
                    )}
                  >
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-bold text-slate-200">
                        Sinal ({Math.round(PERCENTUAL_SINAL * 100)}%)
                      </span>
                      {tipoPagamento === "sinal" && (
                        <span className="w-4 h-4 rounded-full bg-emerald-500 flex items-center justify-center text-slate-950">
                          <Check className="w-3 h-3 stroke-[3]" />
                        </span>
                      )}
                    </div>
                    <p className="text-lg font-black text-emerald-400">
                      {formatarMoeda(valorSinal)}
                    </p>
                    <p className="text-[11px] text-slate-500 mt-1">
                      Restante de {formatarMoeda(valorPendente)} no local
                    </p>
                  </button>

                  {/* Opção Integral */}
                  <button
                    type="button"
                    onClick={() => setTipoPagamento("integral")}
                    className={cn(
                      "p-3 rounded-xl border text-left transition-all duration-200 relative",
                      tipoPagamento === "integral"
                        ? "bg-emerald-500/15 border-emerald-500 text-white shadow-md shadow-emerald-500/10 ring-1 ring-emerald-500/50"
                        : "bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700 hover:text-slate-300"
                    )}
                  >
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-bold text-slate-200">
                        Integral (100%)
                      </span>
                      {tipoPagamento === "integral" && (
                        <span className="w-4 h-4 rounded-full bg-emerald-500 flex items-center justify-center text-slate-950">
                          <Check className="w-3 h-3 stroke-[3]" />
                        </span>
                      )}
                    </div>
                    <p className="text-lg font-black text-emerald-400">
                      {formatarMoeda(valorTotal)}
                    </p>
                    <p className="text-[11px] text-slate-500 mt-1">
                      Pagamento completo sem pendências
                    </p>
                  </button>
                </div>
              </div>
            </div>

            {/* Total Cobrado Agora */}
            <div className="bg-slate-900/90 rounded-xl p-3.5 border border-slate-800 mt-4 flex items-center justify-between">
              <div>
                <p className="text-xs text-slate-400">Total a pagar agora via Pix</p>
                <p className="text-2xl font-black text-emerald-400">
                  {formatarMoeda(valorCobradoAgora)}
                </p>
              </div>
              <div className="text-right">
                <span className="text-[11px] px-2 py-0.5 rounded bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 font-semibold">
                  {tipoPagamento === "sinal" ? "Sinal (40%)" : "Integral (100%)"}
                </span>
              </div>
            </div>
          </div>

          {/* ── Coluna Direita: Formulário de Identificação ── */}
          <div className="space-y-4 flex flex-col justify-between">
            <div className="space-y-3.5">
              {/* Nome */}
              <div className="space-y-1.5">
                <Label className="text-slate-300 text-xs font-semibold flex items-center gap-1.5">
                  <User className="w-3.5 h-3.5 text-emerald-400" /> Nome completo *
                </Label>
                <Input
                  value={dados.nome}
                  onChange={(e) => set("nome", e.target.value)}
                  placeholder="Seu nome completo"
                  className="bg-slate-800/80 border-slate-700 text-white placeholder:text-slate-500 focus:border-emerald-500 focus:ring-emerald-500/20 h-10"
                />
                {errors.nome && (
                  <p className="text-xs text-red-400 font-medium">{errors.nome}</p>
                )}
              </div>

              {/* WhatsApp */}
              <div className="space-y-1.5">
                <Label className="text-slate-300 text-xs font-semibold flex items-center gap-1.5">
                  <Phone className="w-3.5 h-3.5 text-emerald-400" /> WhatsApp *
                </Label>
                <Input
                  value={dados.whatsapp}
                  onChange={(e) => set("whatsapp", mascaraWhatsApp(e.target.value))}
                  placeholder="(11) 99999-0000"
                  inputMode="numeric"
                  className="bg-slate-800/80 border-slate-700 text-white placeholder:text-slate-500 focus:border-emerald-500 focus:ring-emerald-500/20 h-10"
                />
                {errors.whatsapp && (
                  <p className="text-xs text-red-400 font-medium">{errors.whatsapp}</p>
                )}
              </div>

              {/* CPF */}
              <div className="space-y-1.5">
                <Label className="text-slate-300 text-xs font-semibold flex items-center gap-1.5">
                  <CreditCard className="w-3.5 h-3.5 text-emerald-400" /> CPF *
                </Label>
                <Input
                  value={dados.cpf}
                  onChange={(e) => set("cpf", mascaraCPF(e.target.value))}
                  placeholder="000.000.000-00"
                  inputMode="numeric"
                  className="bg-slate-800/80 border-slate-700 text-white placeholder:text-slate-500 focus:border-emerald-500 focus:ring-emerald-500/20 h-10"
                />
                {errors.cpf && (
                  <p className="text-xs text-red-400 font-medium">{errors.cpf}</p>
                )}
              </div>

              {/* Esporte (opcional) */}
              <div className="space-y-1.5">
                <Label className="text-slate-300 text-xs font-semibold">
                  Esporte <span className="text-slate-500 font-normal">(opcional)</span>
                </Label>
                <select
                  value={dados.esporte}
                  onChange={(e) => set("esporte", e.target.value)}
                  className="w-full h-10 px-3 rounded-md bg-slate-800/80 border border-slate-700 text-slate-200 text-sm focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/20"
                >
                  <option value="">Não informar</option>
                  {ESPORTES.map((e) => (
                    <option key={e} value={e}>
                      {e}
                    </option>
                  ))}
                </select>
                {dados.esporte && (
                  <p className="text-[11px] text-emerald-400">
                    ✓ Prepararemos a quadra para {dados.esporte}.
                  </p>
                )}
              </div>

              {/* Observações */}
              <div className="space-y-1.5">
                <Label className="text-slate-300 text-xs font-semibold">
                  Observações <span className="text-slate-500 font-normal">(opcional)</span>
                </Label>
                <Input
                  value={dados.observacoes}
                  onChange={(e) => set("observacoes", e.target.value)}
                  placeholder="Observações adicionais (opcional)"
                  className="bg-slate-800/80 border-slate-700 text-white placeholder:text-slate-500 focus:border-emerald-500 h-10"
                />
              </div>

              {/* Termos e Aviso WhatsApp */}
              <div className="bg-slate-800/40 rounded-xl p-3 border border-slate-700/50 space-y-2">
                <p className="text-[11px] text-slate-400 leading-relaxed">
                  <strong className="text-slate-300">Política de cancelamento:</strong>{" "}
                  Cancelamentos com mais de{" "}
                  <strong className="text-white">
                    {TOLERANCIA_CANCELAMENTO_HORAS}h de antecedência
                  </strong>{" "}
                  são reembolsados integralmente.
                </p>
                <p className="text-[11px] text-emerald-400 font-medium flex items-center gap-1.5">
                  <ShieldCheck className="w-3.5 h-3.5 flex-shrink-0" />
                  A confirmação da sua reserva será enviada pelo WhatsApp.
                </p>
              </div>
            </div>

            <Button
              onClick={handleSubmit}
              className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold h-12 rounded-xl gap-2 mt-4 text-sm shadow-lg shadow-emerald-500/20"
            >
              Ir para pagamento Pix <ChevronRight className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { formatarMoeda } from "@/lib/constants";
import { CheckCircle2, X, ArrowLeft } from "lucide-react";

// ── Fake QR Code SVG ──────────────────────────────────────────────────────────

const QR_ROWS = [
  "1111111011101111111",
  "1000001001001000001",
  "1011101010101011101",
  "1011101001011011101",
  "1011101010101011101",
  "1000001001001000001",
  "1111111010101111111",
  "0000000001100000000",
  "1101011111001011011",
  "0010100101010100100",
  "1001011010101011001",
  "0100000001010010010",
  "1101011011011011011",
  "0000000001110001001",
  "1111111010101110111",
  "1000001001011001001",
  "1011101011001010111",
  "1000001001010100001",
  "1111111010101111111",
];

function FakeQrCode() {
  const size = 19;
  const cellSize = 10;
  const total = size * cellSize;

  return (
    <svg
      width={total}
      height={total}
      viewBox={`0 0 ${total} ${total}`}
      className="rounded-lg"
      style={{ imageRendering: "pixelated" }}
    >
      <rect width={total} height={total} fill="white" />
      {QR_ROWS.map((row, y) =>
        row.split("").map((cell, x) =>
          cell === "1" ? (
            <rect
              key={`${x}-${y}`}
              x={x * cellSize}
              y={y * cellSize}
              width={cellSize}
              height={cellSize}
              fill="#0f172a"
            />
          ) : null
        )
      )}
    </svg>
  );
}

// ── Modal ─────────────────────────────────────────────────────────────────────

interface Props {
  open: boolean;
  tipoPagamento: "sinal" | "integral";
  valorSinal: number;
  valorTotal: number;
  nomeCliente: string;
  onSimularPagamento: (tipo: "sinal" | "integral") => void;
  onVoltar: () => void;
  onCancelar: () => void;
}

export function ModalPix({
  open,
  tipoPagamento,
  valorSinal,
  valorTotal,
  nomeCliente,
  onSimularPagamento,
  onVoltar,
  onCancelar,
}: Props) {
  const valorCobrado = tipoPagamento === "sinal" ? valorSinal : valorTotal;
  const valorRestante = valorTotal - valorSinal;

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onCancelar()}>
      <DialogContent className="bg-slate-900 border-slate-700 text-white max-w-sm mx-auto">
        <DialogHeader>
          <div className="flex items-center justify-between">
            <button
              onClick={onVoltar}
              className="text-slate-400 hover:text-white transition-colors p-1 -ml-1 rounded-lg hover:bg-slate-800"
              title="Voltar para dados e revisão"
            >
              <ArrowLeft className="w-4 h-4" />
            </button>
            <DialogTitle className="text-xl font-bold text-center flex-1 pr-4">
              Pagamento via Pix
            </DialogTitle>
          </div>
        </DialogHeader>

        <div className="flex flex-col items-center gap-4 pt-1">
          {/* Badge de tipo de pagamento */}
          <div className="text-center">
            <span className="inline-block px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider bg-emerald-500/15 border border-emerald-500/30 text-emerald-400">
              {tipoPagamento === "sinal" ? "Pagamento do Sinal (40%)" : "Pagamento Integral (100%)"}
            </span>

            {/* Valor em destaque */}
            <p className="text-4xl font-black text-white mt-2">
              {formatarMoeda(valorCobrado)}
            </p>

            {tipoPagamento === "sinal" ? (
              <p className="text-xs text-slate-400 mt-1">
                Restante de <strong className="text-slate-300">{formatarMoeda(valorRestante)}</strong> no dia do jogo
              </p>
            ) : (
              <p className="text-xs text-emerald-400 font-medium mt-1">
                ✓ Valor total quitado sem pendências
              </p>
            )}
          </div>

          {/* QR Code */}
          <div className="p-3 bg-white rounded-2xl shadow-lg shadow-black/30">
            <FakeQrCode />
          </div>

          <div className="text-center space-y-1">
            <p className="text-xs text-slate-400">
              Chave Pix: <span className="text-white font-mono font-semibold">reservei@complexo.com</span>
            </p>
            <p className="text-[11px] text-slate-500">
              Após o pagamento, a confirmação será enviada via WhatsApp.
            </p>
          </div>

          <Separator className="bg-slate-700/50 w-full" />

          {/* Identificação */}
          <div className="w-full bg-slate-800/50 rounded-xl p-3 text-sm">
            <div className="flex justify-between items-center">
              <span className="text-slate-400 text-xs">Titular</span>
              <span className="text-slate-200 font-semibold text-sm">{nomeCliente || "—"}</span>
            </div>
          </div>

          {/* Aviso ambiente de dev */}
          <div className="w-full bg-amber-500/10 border border-amber-500/20 rounded-xl p-2.5">
            <p className="text-[11px] text-amber-400 text-center leading-relaxed">
              🛠️ <strong>Ambiente de demonstração.</strong> Clique abaixo para simular a aprovação instantânea.
            </p>
          </div>

          {/* Ações */}
          <div className="w-full space-y-2">
            <Button
              onClick={() => onSimularPagamento(tipoPagamento)}
              className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold h-12 rounded-xl gap-2 shadow-lg shadow-emerald-500/20 text-sm"
            >
              <CheckCircle2 className="w-5 h-5" />
              Simular Pagamento Aprovado
            </Button>
            <Button
              variant="ghost"
              onClick={onCancelar}
              className="w-full text-slate-500 hover:text-red-400 hover:bg-red-500/10 h-9 gap-1.5 text-xs"
            >
              <X className="w-3.5 h-3.5" />
              Cancelar reserva
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

