  if (btn14) {
    btn14.click();
    return "clicked 14:00";
  }
  return "not found";
})()

(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const btnCart = buttons.find(b => b.textContent.includes('Ver reserva'));
  if (btnCart) {
    btnCart.click();
    return "clicked cart button";
  }
  const btnCont = buttons.find(b => b.textContent.includes('Continuar'));
  if (btnCont) {
    btnCont.click();
    return "clicked continuar directly";
  }
  return "not found";
})()

(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const btnContinuar = buttons.find(b => b.textContent.includes('Continuar'));
  if (btnContinuar) {
    btnContinuar.click();
    return "clicked continuar";
  }
  return "not found";
})()

(() => {
  const dialogContent = document.querySelector('[data-slot="dialog-content"]');
  if (dialogContent) {
    dialogContent.scrollTop = 300;
    return "scrolled dialog";
  }
  return "dialog not found";
})()

