/** Retorna a data de hoje no formato "YYYY-MM-DD" usando o timezone local */
export function getHoje(): string {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Verifica se o horário já passou na data selecionada (com tolerância de 10 minutos) */
export function isHorarioPassado(horario: string, dataISO: string): boolean {
  const agora = new Date();

  // Extrair ano, mês e dia da dataISO selecionada
  const [year, month, day] = dataISO.split("-").map(Number);

  // Extrair hora e minuto do slot
  const [horaStr, minStr] = horario.split(":");
  const hora = parseInt(horaStr, 10);
  const min = parseInt(minStr, 10);

  // Monta a data/hora do slot
  const horaSlot = new Date(year, month - 1, day, hora, min, 0, 0);

  // Subtrair 10 minutos do horário do slot para ser a hora limite de reserva.
  const horaLimite = new Date(horaSlot.getTime() - 10 * 60000);

  // Se o momento atual for maior que a hora limite, não pode mais reservar
  return agora > horaLimite;
}

